// GENERATED by scripts/sync-shared.mjs from src/lib. Do not edit by hand.
// The "editor's brief": everything a scheduled editorial task should read
// before choosing what to write. Served by the `brief` edge function in
// production and copyable from Settings in demo mode. Shared code, so both agree.
import type { AppState, Item, Series } from "./types.ts";
import { priorityLabel } from "./ledger.ts";
import { seriesProgress } from "./curation.ts";

export interface EditorBrief {
  generatedAt: string;
  schemaVersion: 1;
  interests: {
    name: string; description: string; related: string[]; priority: string; weight: number;
    confidence: number; origin: string; status: string; locked: boolean; until?: string;
  }[];
  /** Hard rules. Never publish anything matching these. */
  exclusions: { topics: string[]; senders: string[]; mutedCategories: string[] };
  preferences: {
    evergreenBalance: number; discovery: number; focus: number; length: string; technicality: string;
    circleFrequency: string; activeSeries: number; formatMix: Record<string, number>; writingStyleNote: string;
  };
  followedTopics: string[];
  /** Direct requests from the reader, newest first. Treat as authoritative. */
  readerRequests: { at: string; text: string; topic?: string }[];
  seriesFeedback: { seriesId: string; answer: "yes" | "no"; at: string }[];
  activeSeries: { id: string; title: string; chaptersRead: number; totalChapters: number; lastOpened?: string }[];
  people: { name: string; relationship: string; closeness: number; permittedProfiles: { label: string; url: string }[]; interestedIn: string[]; lastChecked?: string }[];
  sourcePrefs: { prioritisedSenders: string[]; excludedSenders: string[]; mutedCategories: string[]; approvedLabels: string[] };
  /** For duplicate avoidance */
  recentlyPublished: { id: string; headline: string; format: string; topics: string[]; publishedAt: string }[];
  inventory: { unread: number; unreadByFormat: Record<string, number>; targetUnread: string };
  recentFeedback: { type: string; itemId?: string; topic?: string; at: string }[];
}

export function buildBrief(state: AppState, items: Item[], series: Series[], now = new Date()): EditorBrief {
  const published = items.filter((i) => i.status !== "archived");
  const unread = published.filter((i) => i.format !== "series_chapter" && !state.progress[i.id]?.status?.startsWith("read") && !state.dismissed.includes(i.id));
  const unreadByFormat: Record<string, number> = {};
  for (const i of unread) unreadByFormat[i.format] = (unreadByFormat[i.format] ?? 0) + 1;

  const active = series
    .filter((s) => state.seriesStarted[s.id])
    .map((s) => ({ s, p: seriesProgress(state, s, items) }))
    .filter((x) => !x.p.complete)
    .map((x) => ({ id: x.s.id, title: x.s.title, chaptersRead: x.p.read, totalChapters: x.s.totalChapters, lastOpened: x.p.lastOpened }));

  return {
    generatedAt: now.toISOString(),
    schemaVersion: 1,
    interests: state.interests.map((i) => ({
      name: i.name, description: i.description, related: i.related, priority: priorityLabel(i.weight), weight: i.weight,
      confidence: i.confidence, origin: i.origin, status: i.status, locked: i.locked, until: i.until,
    })),
    exclusions: {
      topics: [...new Set([...state.prefs.excludedTopics, ...state.interests.filter((i) => i.status === "excluded").map((i) => i.name)])],
      senders: state.sourcePrefs.excludedSenders,
      mutedCategories: state.sourcePrefs.mutedCategories,
    },
    preferences: {
      evergreenBalance: state.prefs.evergreenBalance, discovery: state.prefs.discovery, focus: state.prefs.focus,
      length: state.prefs.length, technicality: state.prefs.technicality, circleFrequency: state.prefs.circleFrequency,
      activeSeries: state.prefs.activeSeries, formatMix: state.prefs.formatMix, writingStyleNote: state.prefs.writingStyleNote,
    },
    followedTopics: state.followed,
    readerRequests: state.feedback
      .filter((f) => f.type === "reader-request")
      .slice(0, 20)
      .map((f) => ({ at: f.at, text: f.reason ?? "", topic: f.topic })),
    seriesFeedback: state.feedback
      .filter((f) => f.seriesId && (f.type === "series-yes" || f.type === "series-no"))
      .map((f) => ({ seriesId: f.seriesId!, answer: f.type === "series-yes" ? "yes" as const : "no" as const, at: f.at })),
    activeSeries: active,
    people: state.people.map((p) => ({
      name: p.name, relationship: p.relationship, closeness: p.closeness,
      permittedProfiles: p.profiles.filter((x) => x.permitted).map(({ label, url }) => ({ label, url })),
      interestedIn: p.interestedIn, lastChecked: p.lastChecked,
    })),
    sourcePrefs: state.sourcePrefs,
    recentlyPublished: published
      .sort((a, b) => b.publishedAt.localeCompare(a.publishedAt))
      .slice(0, 120)
      .map((i) => ({ id: i.id, headline: i.headline, format: i.format, topics: i.topics, publishedAt: i.publishedAt })),
    inventory: { unread: unread.length, unreadByFormat, targetUnread: "about 12-25 unread standalone items; publish nothing if the feed is already healthy and nothing is genuinely worth adding" },
    recentFeedback: state.feedback
      .filter((f) => f.type !== "reader-request")
      .slice(0, 40)
      .map((f) => ({ type: f.type, itemId: f.itemId, topic: f.topic, at: f.at })),
  };
}
